                        new_vy_b = state[ob]['vy'] + rv_dot_n * ny

                        state[oa]['vx'], state[oa]['vy'] = new_vx_a, new_vy_a
                        state[ob]['vx'], state[ob]['vy'] = new_vx_b, new_vy_b

                        # Record collision if not already recorded
                        pair_key = (min(oa, ob), max(oa, ob))
                        if pair_key not in collided:
                            collided.add(pair_key)
                            outcomes.append({
                                "time": float(frame),
                                "kind": "collision",
                                "entities": [oa, ob],
                                "value": None,
                                "src": []
                            })

    return outcomes

import re

def entities(doc, scope) -> list:
    for node in scope_nodes(doc, scope):
        if node['kind'] == 'list' and 'Objects' in node['title']:
            result = []
            for i, line in enumerate(node['lines']):
                m = re.match(r'(Object \d+):\s*(.+)', line.strip())
                if m:
                    result.append({"id": m.group(1), "description": m.group(2)})
            return result
    return []

def recorded_end(doc, scope) -> float or None:
    for node in scope_nodes(doc, scope):
        if node['kind'] == 'table' and 'Motion log' in node['title']:
            rows = table_rows(node)
            if not rows:
                return None
            max_frame = max(int(r[1]['frame']) for r in rows)
            return float(max_frame)
    return None

def inputs(doc, scope) -> list:
    for node in scope_nodes(doc, scope):
        if node['kind'] == 'list' and 'Events' in node['title']:
            result = []
            for line_idx, line in enumerate(node['lines']):
                # Object enters the scene
                m_enter = re.match(r'Frame\s+(\d+):\s+(.+?)\s+enters the scene\.', line)
                if m_enter:
                    frame = int(m_enter.group(1))
                    obj_desc = m_enter.group(2)
                    om = re.match(r'(Object \d+)\s+\(.+\)', obj_desc)
                    if om:
                        obj_id = om.group(1)
                        result.append({
                            "id": f"enter_{obj_id}_{frame}",
                            "time": float(frame),
                            "kind": "enter",
                            "entities": [obj_id],
                            "fields": {},
                            "src": [[node['node_id'], line_idx]]
                        })
                    continue
                # Object is in view when the video begins
                m_begin = re.match(r'Frame\s+(\d+):\s+(.+?)\s+is in view when the video begins\.', line)
                if m_begin:
                    frame = int(m_begin.group(1))
                    obj_desc = m_begin.group(2)
                    om = re.match(r'(Object \d+)\s+\(.+\)', obj_desc)
                    if om:
                        obj_id = om.group(1)
                        result.append({
                            "id": f"begin_{obj_id}_{frame}",
                            "time": float(frame),
                            "kind": "begin_view",
                            "entities": [obj_id],
                            "fields": {},
                            "src": [[node['node_id'], line_idx]]
                        })
            return result
    return []

def outcomes(doc, scope) -> list:
    for node in scope_nodes(doc, scope):
        if node['kind'] == 'list' and 'Events' in node['title']:
            result = []
            def get_obj_id(desc):
                m = re.match(r'(Object \d+)\s+\(.+\)', desc)
                return m.group(1) if m else None

            for line_idx, line in enumerate(node['lines']):
                # Collision event
                m_col = re.match(r'Frame\s+(\d+):\s+(.+?)\s+collides with\s+(.+?)\.', line)
                if m_col:
                    frame = int(m_col.group(1))
                    obj_a = get_obj_id(m_col.group(2))
                    obj_b = get_obj_id(m_col.group(3))
                    if obj_a and obj_b:
                        result.append({
                            "time": float(frame),
                            "kind": "collision",
                            "entities": [obj_a, obj_b],
                            "value": None,
                            "src": [[node['node_id'], line_idx]]
                        })
                    continue

                # Exit event
                m_exit = re.match(r'Frame\s+(\d+):\s+(.+?)\s+exits the scene\.', line)
                if m_exit:
                    frame = int(m_exit.group(1))
                    obj_id = get_obj_id(m_exit.group(2))
                    if obj_id:
                        result.append({
                            "time": float(frame),
                            "kind": "exit",
                            "entities": [obj_id],
                            "value": None,
                            "src": [[node['node_id'], line_idx]]
                        })
            return result
    return []

def params(doc, scope) -> dict:
    return {"stationary_threshold": 0.1}


