import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    import re
    from collections import defaultdict

    stationary_threshold = params.get("stationary_threshold", 0.1)

    DT = 0.03  # seconds per frame
    FRICTION = 0.9975  # velocity retention per frame
    COLLISION_DIST = 0.45  # distance threshold for collision detection
    EXIT_Y = -1.7  # y threshold for exit

    # Build motion logs for this scope
    scope_prefix = scope + ': '
    motion_logs = defaultdict(list)

    for node in doc['nodes']:
        if node['kind'] == 'table' and 'Motion log' in node['title']:
            if node['title'].startswith(scope_prefix):
                rows = table_rows(node)
                for _, cells in rows:
                    obj_name = cells['object']
                    obj_num = obj_name.split()[0]
                    oid = f"Object {obj_num}"
                    frame = int(cells['frame'])
                    if not cells['x'] or not cells['y']:
                        continue
                    motion_logs[oid].append({
                        'frame': frame,
                        'x': float(cells['x']),
                        'y': float(cells['y']),
                        'vx': float(cells['vx']),
                        'vy': float(cells['vy'])
                    })

    for oid in motion_logs:
        motion_logs[oid].sort(key=lambda p: p['frame'])

    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end if rec_end is not None else 127
    if start is None:
        start = 0.0

    def get_state_at(oid, time):
        if oid not in motion_logs or not motion_logs[oid]:
            return {'x': 0.0, 'y': 0.0, 'vx': 0.0, 'vy': 0.0}
        pts = motion_logs[oid]
        best = pts[0]
        for p in pts:
            if p['frame'] <= time:
                best = p
            else:
                break
        dt_frames = time - best['frame']
        return {
            'x': best['x'] + best['vx'] * dt_frames * DT,
            'y': best['y'] + best['vy'] * dt_frames * DT,
            'vx': best['vx'],
            'vy': best['vy']
        }

    state = {}
    enter_schedule = []

    for inp in inputs:
        if inp['kind'] not in ('enter', 'begin_view'):
            continue
        t = inp['time']
        for oid in inp['entities']:
            if oid in state:
                continue
            if t <= start:
                state[oid] = get_state_at(oid, start)
            else:
                enter_schedule.append((t, oid))

    enter_schedule.sort()
    enter_idx = 0

    outcomes = []
    exited = set()
    collided_pairs = set()

    start_frame = int(math.ceil(start))
    horizon_frame = int(horizon)

    for frame in range(start_frame, horizon_frame + 1):
        while enter_idx < len(enter_schedule) and enter_schedule[enter_idx][0] <= frame:
            ent_frame, oid = enter_schedule[enter_idx]
            enter_idx += 1
            if oid not in state:
                state[oid] = get_state_at(oid, ent_frame)

        oids = sorted(state.keys())

        # Apply friction
        for oid in oids:
            obj = state[oid]
            obj['vx'] *= FRICTION
            obj['vy'] *= FRICTION

        # Update positions
        for oid in oids:
            obj = state[oid]
            obj['x'] += obj['vx'] * DT
            obj['y'] += obj['vy'] * DT

        # Check for exits
        for oid in list(oids):
            obj = state[oid]
            if obj['y'] < EXIT_Y:
                if oid not in exited:
                    exited.add(oid)
                    outcomes.append({
                        "time": float(frame),
                        "kind": "exit",
                        "entities": [oid],
                        "value": None,
                        "src": []
                    })
                    del state[oid]
                    oids.remove(oid)

        # Check for collisions
        for i in range(len(oids)):
            for j in range(i + 1, len(oids)):
                oa = oids[i]
                ob = oids[j]

                dx = state[oa]['x'] - state[ob]['x']
                dy = state[oa]['y'] - state[ob]['y']
                dist = math.sqrt(dx * dx + dy * dy)

                if dist < COLLISION_DIST:
                    pair = (min(oa, ob), max(oa, ob))
                    if pair in collided_pairs:
                        continue
                    collided_pairs.add(pair)

                    if dist > 1e-8:
                        nx, ny = dx / dist, dy / dist
                    else:
                        nx, ny = 1.0, 0.0

                    rvx = state[oa]['vx'] - state[ob]['vx']
                    rvy = state[oa]['vy'] - state[ob]['vy']
                    rv_dot_n = rvx * nx + rvy * ny

                    if rv_dot_n < 0:
                        state[oa]['vx'] -= rv_dot_n * nx
                        state[oa]['vy'] -= rv_dot_n * ny
                        state[ob]['vx'] += rv_dot_n * nx
                        state[ob]['vy'] += rv_dot_n * ny

                    outcomes.append({
                        "time": float(frame),
                        "kind": "collision",
                        "entities": [oa, ob],
                        "value": None,
                        "src": []
                    })

    return outcomes
